const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const sqlite = sqliteLibrary(b, target, optimize);

    const sqlite_c = b.addTranslateC(.{
        .root_source_file = sqlite.header,
        .target = target,
        .optimize = optimize,
    });

    const app_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .imports = &.{
            .{ .name = "sqlite_c", .module = sqlite_c.createModule() },
        },
    });
    app_module.linkLibrary(sqlite.lib);

    const exe = b.addExecutable(.{
        .name = "app",
        .root_module = app_module,
    });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the server: zig build run -- <port>");
    run_step.dependOn(&run_cmd.step);

    const unit_tests = b.addTest(.{ .root_module = app_module });
    const run_unit_tests = b.addRunArtifact(unit_tests);
    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&run_unit_tests.step);
}

const Sqlite = struct {
    lib: *std.Build.Step.Compile,
    header: std.Build.LazyPath,
};

/// Builds the SQLite amalgamation fetched through build.zig.zon as a static library.
fn sqliteLibrary(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) Sqlite {
    const upstream = b.dependency("sqlite", .{});

    const module = b.createModule(.{
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    module.addCSourceFile(.{
        .file = upstream.path("sqlite3.c"),
        .flags = &.{
            "-std=c99",
            "-DSQLITE_THREADSAFE=2", // connections are never shared between threads unguarded
            "-DSQLITE_DQS=0",
            "-DSQLITE_DEFAULT_FOREIGN_KEYS=1",
            "-DSQLITE_DEFAULT_MEMSTATUS=0",
            "-DSQLITE_DEFAULT_WAL_SYNCHRONOUS=1",
            "-DSQLITE_LIKE_DOESNT_MATCH_BLOBS",
            "-DSQLITE_OMIT_DEPRECATED",
            "-DSQLITE_OMIT_LOAD_EXTENSION",
            "-DSQLITE_OMIT_SHARED_CACHE",
            "-DSQLITE_USE_ALLOCA",
        },
    });
    module.addIncludePath(upstream.path("."));

    const lib = b.addLibrary(.{
        .name = "sqlite3",
        .root_module = module,
        .linkage = .static,
    });

    return .{ .lib = lib, .header = upstream.path("sqlite3.h") };
}

//! HTTP/1.1 server: accepts connections, runs each one concurrently, reads
//! requests and hands them to `router.dispatch`.

const std = @import("std");
const Io = std.Io;
const net = std.Io.net;
const Allocator = std.mem.Allocator;
const Store = @import("Store.zig");
const router = @import("router.zig");
const web = @import("web.zig");

const log = std.log.scoped(.server);

const Server = @This();

gpa: Allocator,
io: Io,
store: *Store,
options: Options,

pub const Options = struct {
    /// Larger request bodies are answered with 413.
    max_body_len: usize = 1024 * 1024,
    /// Also the maximum size of a request head; larger heads get 431.
    read_buffer_len: usize = 16 * 1024,
    write_buffer_len: usize = 16 * 1024,
};

/// Accepts connections on `address` until the task is canceled.
pub fn serve(server: *Server, address: net.IpAddress) !void {
    const io = server.io;
    var listener = try address.listen(io, .{ .reuse_address = true });
    defer listener.deinit(io);
    log.info("listening on {f}", .{address});

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.Canceled => return error.Canceled,
            else => {
                log.err("accept: {t}", .{err});
                continue;
            },
        };
        connections.concurrent(io, handleConnection, .{ server, stream }) catch |err| {
            log.warn("serving connection inline: {t}", .{err});
            handleConnection(server, stream);
        };
    }
}

fn handleConnection(server: *Server, stream: net.Stream) void {
    const io = server.io;
    defer stream.close(io);

    const read_buffer = server.gpa.alloc(u8, server.options.read_buffer_len) catch return;
    defer server.gpa.free(read_buffer);
    const write_buffer = server.gpa.alloc(u8, server.options.write_buffer_len) catch return;
    defer server.gpa.free(write_buffer);

    var stream_reader = stream.reader(io, read_buffer);
    var stream_writer = stream.writer(io, write_buffer);
    var http: std.http.Server = .init(&stream_reader.interface, &stream_writer.interface);

    var arena: std.heap.ArenaAllocator = .init(server.gpa);
    defer arena.deinit();

    while (true) {
        _ = arena.reset(.{ .retain_with_limit = 64 * 1024 });

        var request = http.receiveHead() catch |err| {
            switch (err) {
                error.HttpConnectionClosing, error.ReadFailed => {},
                error.HttpHeadersOversize => respondRaw(&stream_writer.interface, "431 Request Header Fields Too Large"),
                error.HttpHeadersInvalid, error.HttpRequestTruncated => respondRaw(&stream_writer.interface, "400 Bad Request"),
            }
            return;
        };
        const keep_alive = server.handleRequest(&request, arena.allocator()) catch |err| {
            log.debug("connection closed: {t}", .{err});
            return;
        };
        if (!keep_alive) return;
    }
}

/// Answers one request. Returns whether the connection can serve another.
fn handleRequest(server: *Server, request: *std.http.Server.Request, arena: Allocator) !bool {
    const head = request.head;
    // The head's strings live in the read buffer, which reading the body reuses.
    const target = try arena.dupe(u8, head.target);
    const path, const query = splitTarget(target);

    var keep_alive = head.keep_alive;
    var body: []const u8 = "";
    // A request without Content-Length or chunked encoding has no body (RFC 9112,
    // section 6.3); reading one anyway would wait for the client to close. The
    // std server cannot resume such a connection, so it is closed after the response.
    const has_body = head.content_length != null or head.transfer_encoding == .chunked;
    if (head.method.requestHasBody() and !has_body) {
        keep_alive = false;
    } else if (head.method.requestHasBody()) {
        if (head.content_length) |len| if (len > server.options.max_body_len) {
            try respond(request, try tooLarge(arena), false);
            return false;
        };
        const reader = request.readerExpectContinue(&.{}) catch |err| switch (err) {
            error.HttpExpectationFailed => {
                try respond(request, try web.jsonError(arena, .expectation_failed, "unsupported Expect header"), false);
                return false;
            },
            else => |e| return e,
        };
        body = reader.allocRemaining(arena, .limited(server.options.max_body_len + 1)) catch |err| switch (err) {
            error.StreamTooLong => {
                try respond(request, try tooLarge(arena), false);
                return false;
            },
            error.ReadFailed, error.OutOfMemory => |e| return e,
        };
        if (body.len > server.options.max_body_len) {
            try respond(request, try tooLarge(arena), false);
            return false;
        }
    }

    var req: web.Request = .{
        .arena = arena,
        .store = server.store,
        .method = head.method,
        .path = path,
        .query = query,
        .body = body,
    };
    const res = router.dispatch(&req) catch |err| blk: {
        log.err("{t} {s}: {t}", .{ head.method, path, err });
        if (@errorReturnTrace()) |trace| std.debug.dumpErrorReturnTrace(trace);
        keep_alive = false;
        break :blk try web.jsonError(arena, .internal_server_error, "internal error");
    };
    try respond(request, res, keep_alive);
    return keep_alive;
}

fn respond(request: *std.http.Server.Request, res: web.Response, keep_alive: bool) !void {
    var headers: [2]std.http.Header = undefined;
    var len: usize = 0;
    if (res.content_type) |value| {
        headers[len] = .{ .name = "content-type", .value = value };
        len += 1;
    }
    if (res.allow) |value| {
        headers[len] = .{ .name = "allow", .value = value };
        len += 1;
    }
    try request.respond(res.body, .{
        .status = res.status,
        .keep_alive = keep_alive,
        .extra_headers = headers[0..len],
    });
}

fn tooLarge(arena: Allocator) !web.Response {
    return web.jsonError(arena, .payload_too_large, "request body too large");
}

/// Best effort response for requests that could not be parsed.
fn respondRaw(out: *Io.Writer, status_line: []const u8) void {
    out.print("HTTP/1.1 {s}\r\nconnection: close\r\ncontent-length: 0\r\n\r\n", .{status_line}) catch return;
    out.flush() catch return;
}

/// Splits a request target into its path and query string.
fn splitTarget(target: []const u8) struct { []const u8, []const u8 } {
    const without_fragment = target[0 .. std.mem.indexOfScalar(u8, target, '#') orelse target.len];
    const q = std.mem.indexOfScalar(u8, without_fragment, '?') orelse return .{ without_fragment, "" };
    return .{ without_fragment[0..q], without_fragment[q + 1 ..] };
}

test splitTarget {
    const path, const query = splitTarget("/notes?tag=a&q=b");
    try std.testing.expectEqualStrings("/notes", path);
    try std.testing.expectEqualStrings("tag=a&q=b", query);

    const path2, const query2 = splitTarget("/health");
    try std.testing.expectEqualStrings("/health", path2);
    try std.testing.expectEqualStrings("", query2);
}

//! The notes database: one SQLite connection shared by all request handlers.
//!
//! Handlers never touch the connection directly; the data-access modules in
//! `src/store/` call `acquire`/`release` around their queries so requests on
//! different threads are serialized.

const std = @import("std");
const sqlite = @import("sqlite.zig");

const Store = @This();

io: std.Io,
db: sqlite.Db,
mutex: std.Io.Mutex = .init,

/// Bumped whenever `migrations` gains an entry.
const schema_version = migrations.len;

/// Applied in order; entry `i` upgrades a database from version `i` to `i + 1`.
const migrations = [_][:0]const u8{
    \\CREATE TABLE notes (
    \\    -- AUTOINCREMENT: ids are never reused, also after deleting the newest note.
    \\    id    INTEGER PRIMARY KEY AUTOINCREMENT,
    \\    title TEXT NOT NULL,
    \\    body  TEXT NOT NULL DEFAULT ''
    \\);
    \\CREATE TABLE note_tags (
    \\    note_id INTEGER NOT NULL REFERENCES notes (id) ON DELETE CASCADE,
    \\    tag     TEXT NOT NULL,
    \\    PRIMARY KEY (note_id, tag)
    \\) WITHOUT ROWID;
    \\CREATE INDEX note_tags_by_tag ON note_tags (tag, note_id);
    ,
};

pub fn open(io: std.Io, path: [:0]const u8) !Store {
    const db = try sqlite.Db.open(path, .{});
    errdefer db.close();
    try db.exec(
        \\PRAGMA journal_mode = WAL;
        \\PRAGMA synchronous = NORMAL;
        \\PRAGMA foreign_keys = ON;
    );
    try migrate(db);
    return .{ .io = io, .db = db };
}

pub fn close(store: *Store) void {
    store.db.close();
    store.* = undefined;
}

/// Exclusive access to the connection until `release`.
pub fn acquire(store: *Store) std.Io.Cancelable!sqlite.Db {
    try store.mutex.lock(store.io);
    return store.db;
}

pub fn release(store: *Store) void {
    store.mutex.unlock(store.io);
}

fn migrate(db: sqlite.Db) !void {
    const current = blk: {
        const stmt = try db.prepare("PRAGMA user_version");
        defer stmt.finalize();
        _ = try stmt.step();
        break :blk stmt.int(0);
    };
    if (current > schema_version) return error.UnsupportedSchemaVersion;

    for (migrations[@intCast(current)..], @intCast(current + 1)..) |sql, version| {
        try db.exec("BEGIN IMMEDIATE");
        errdefer db.exec("ROLLBACK") catch {};
        try db.exec(sql);
        var buf: [64]u8 = undefined;
        try db.exec(try std.fmt.bufPrintZ(&buf, "PRAGMA user_version = {d}", .{version}));
        try db.exec("COMMIT");
    }
}

test "open creates the schema and is idempotent" {
    var store = try Store.open(std.testing.io, ":memory:");
    defer store.close();
    try migrate(store.db);

    const stmt = try store.db.prepare("SELECT count(*) FROM sqlite_schema WHERE name IN ('notes', 'note_tags')");
    defer stmt.finalize();
    try std.testing.expect(try stmt.step());
    try std.testing.expectEqual(@as(i64, 2), stmt.int(0));
}

//! `PUT /notes/{id}` and `DELETE /notes/{id}`.
//!
//! Data access is in `store/crud.zig`; input validation is shared with
//! `POST /notes` (`model.parseNoteInput`).

const web = @import("../web.zig");
const model = @import("../model.zig");
const store = @import("../store/crud.zig");

/// `PUT /notes/{id}` with `{title, body?, tags?}` (full replacement):
/// 200 and the updated note, 400 or 404.
pub fn update(req: *web.Request, id: i64) !web.Response {
    var diag: model.Diagnostic = .{};
    const input = model.parseNoteInput(req.arena, req.body, &diag) catch |err| switch (err) {
        error.InvalidInput => return web.jsonError(req.arena, .bad_request, diag.message),
        else => |e| return e,
    };
    const note = try store.update(req.store, id, input) orelse
        return web.jsonError(req.arena, .not_found, "note not found");
    return web.json(req.arena, .ok, note);
}

/// `DELETE /notes/{id}`: 204 with an empty body, or 404.
pub fn remove(req: *web.Request, id: i64) !web.Response {
    if (!try store.remove(req.store, id)) return web.jsonError(req.arena, .not_found, "note not found");
    return web.no_content;
}

//! `GET /health`: liveness probe.

const web = @import("../web.zig");

pub fn get(req: *web.Request) !web.Response {
    _ = req;
    return web.text(.ok, "ok");
}

//! `GET /notes` with the optional query parameters `tag`, `q`, `after` and
//! `limit` (see SPEC.md).

const std = @import("std");
const Allocator = std.mem.Allocator;
const web = @import("../web.zig");
const model = @import("../model.zig");
const store = @import("../store/list.zig");

/// `GET /notes`: 200 and `{"notes": [note, ...]}` ordered by id, or 400.
pub fn list(req: *web.Request) !web.Response {
    var diag: model.Diagnostic = .{};
    const filter = parseFilter(req.arena, req.query, &diag) catch |err| switch (err) {
        error.InvalidInput => return web.jsonError(req.arena, .bad_request, diag.message),
        else => |e| return e,
    };
    const notes = try store.list(req.store, req.arena, filter);
    return web.json(req.arena, .ok, .{ .notes = notes });
}

/// Parses the query string of `GET /notes`. Unknown parameters are ignored;
/// when a parameter is repeated, the last value wins.
pub fn parseFilter(arena: Allocator, query: []const u8, diag: *model.Diagnostic) model.ParseError!store.Filter {
    var filter: store.Filter = .{};
    var pairs = std.mem.splitScalar(u8, query, '&');
    while (pairs.next()) |pair| {
        if (pair.len == 0) continue;
        const eq = std.mem.indexOfScalar(u8, pair, '=');
        const name = try formDecode(arena, pair[0 .. eq orelse pair.len]);
        const value = try formDecode(arena, if (eq) |i| pair[i + 1 ..] else "");

        if (std.mem.eql(u8, name, "tag")) {
            filter.tag = value;
        } else if (std.mem.eql(u8, name, "q")) {
            filter.text = value;
        } else if (std.mem.eql(u8, name, "after")) {
            filter.after = parseInteger(i64, value) orelse
                return invalid(diag, "after must be an integer");
        } else if (std.mem.eql(u8, name, "limit")) {
            const limit = parseInteger(u32, value) orelse 0;
            if (limit < 1 or limit > store.max_limit) return invalid(diag, "limit must be an integer from 1 to 100");
            filter.limit = limit;
        }
    }
    return filter;
}

/// A base-10 integer: an optional `-` followed by digits only (no `+`,
/// underscores or spaces). Null if malformed or out of range for `T`.
fn parseInteger(comptime T: type, text: []const u8) ?T {
    const digits = if (std.mem.startsWith(u8, text, "-")) text[1..] else text;
    if (digits.len == 0) return null;
    for (digits) |ch| if (!std.ascii.isDigit(ch)) return null;
    return std.fmt.parseInt(T, text, 10) catch null;
}

/// Decodes an `application/x-www-form-urlencoded` component: `+` is a
/// space and `%XX` a byte. A `%` not followed by two hex digits is kept as is.
fn formDecode(arena: Allocator, encoded: []const u8) Allocator.Error![]const u8 {
    if (std.mem.indexOfAny(u8, encoded, "%+") == null) return encoded;
    const out = try arena.alloc(u8, encoded.len);
    var len: usize = 0;
    var i: usize = 0;
    while (i < encoded.len) : (len += 1) {
        const ch = encoded[i];
        if (ch == '%' and i + 2 < encoded.len and
            std.ascii.isHex(encoded[i + 1]) and std.ascii.isHex(encoded[i + 2]))
        {
            out[len] = std.fmt.parseInt(u8, encoded[i + 1 ..][0..2], 16) catch unreachable;
            i += 3;
        } else {
            out[len] = if (ch == '+') ' ' else ch;
            i += 1;
        }
    }
    return out[0..len];
}

fn invalid(diag: *model.Diagnostic, message: []const u8) error{InvalidInput} {
    diag.message = message;
    return error.InvalidInput;
}

const testing = std.testing;

test formDecode {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try testing.expectEqualStrings("plain", try formDecode(a, "plain"));
    try testing.expectEqualStrings("a b c", try formDecode(a, "a+b%20c"));
    try testing.expectEqualStrings("100%", try formDecode(a, "100%25"));
    try testing.expectEqualStrings("é&=", try formDecode(a, "%C3%A9%26%3d"));
    try testing.expectEqualStrings("%zz%4", try formDecode(a, "%zz%4"));
    try testing.expectEqualStrings("%", try formDecode(a, "%"));
}

test parseInteger {
    try testing.expectEqual(@as(?i64, 42), parseInteger(i64, "42"));
    try testing.expectEqual(@as(?i64, -3), parseInteger(i64, "-3"));
    try testing.expectEqual(@as(?i64, 7), parseInteger(i64, "007"));
    try testing.expectEqual(null, parseInteger(i64, ""));
    try testing.expectEqual(null, parseInteger(i64, "-"));
    try testing.expectEqual(null, parseInteger(i64, "+1"));
    try testing.expectEqual(null, parseInteger(i64, "1_0"));
    try testing.expectEqual(null, parseInteger(i64, "1.5"));
    try testing.expectEqual(null, parseInteger(i64, " 1"));
    try testing.expectEqual(null, parseInteger(i64, "99999999999999999999"));
    try testing.expectEqual(null, parseInteger(u32, "-1"));
}

test parseFilter {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var diag: model.Diagnostic = .{};

    const defaults = try parseFilter(a, "", &diag);
    try testing.expectEqual(store.Filter{}, defaults);

    const full = try parseFilter(a, "tag=work&q=Hello+there&after=2&limit=10&other=x&&flag", &diag);
    try testing.expectEqualStrings("work", full.tag.?);
    try testing.expectEqualStrings("Hello there", full.text.?);
    try testing.expectEqual(@as(?i64, 2), full.after);
    try testing.expectEqual(@as(u32, 10), full.limit);

    try testing.expectEqual(@as(u32, 100), (try parseFilter(a, "limit=100", &diag)).limit);
    try testing.expectEqual(@as(u32, 1), (try parseFilter(a, "limit=1", &diag)).limit);
    try testing.expectEqualStrings("", (try parseFilter(a, "q=", &diag)).text.?);

    const bad = [_][]const u8{
        "limit=0",           "limit=101", "limit=-1", "limit=abc", "limit=",     "limit", "limit=1.0",
        "limit=99999999999", "after=x",   "after=",   "after=1e3", "after=%2B1",
    };
    for (bad) |query| {
        diag = .{};
        try testing.expectError(error.InvalidInput, parseFilter(a, query, &diag));
        try testing.expect(diag.message.len > 0);
    }
}

//! `POST /notes` and `GET /notes/{id}`.

const std = @import("std");
const web = @import("../web.zig");
const model = @import("../model.zig");
const store = @import("../store/notes.zig");

/// `POST /notes` with `{title, body?, tags?}`: 201 and the created note.
pub fn create(req: *web.Request) !web.Response {
    var diag: model.Diagnostic = .{};
    const input = model.parseNoteInput(req.arena, req.body, &diag) catch |err| switch (err) {
        error.InvalidInput => return web.jsonError(req.arena, .bad_request, diag.message),
        else => |e| return e,
    };
    const note = try store.create(req.store, input);
    return web.json(req.arena, .created, note);
}

/// `GET /notes/{id}`: 200 and the note, or 404.
pub fn show(req: *web.Request, id: i64) !web.Response {
    const note = try store.get(req.store, req.arena, id) orelse
        return web.jsonError(req.arena, .not_found, "note not found");
    return web.json(req.arena, .ok, note);
}

//! `GET /stats` and `GET /tags`.

const std = @import("std");
const web = @import("../web.zig");
const store = @import("../store/stats.zig");

/// `GET /stats`: 200 and `{"notes": <count>, "tags": {"<tag>": <count>, ...}}`.
pub fn stats(req: *web.Request) !web.Response {
    const result = try store.stats(req.store, req.arena);
    return web.json(req.arena, .ok, .{
        .notes = result.notes,
        .tags = TagObject{ .counts = result.tags },
    });
}

/// `GET /tags`: 200 and `{"tags": [{"tag": "<tag>", "count": <n>}, ...]}`
/// ordered by count descending, then tag ascending.
pub fn tags(req: *web.Request) !web.Response {
    const counts = try store.tags(req.store, req.arena, .count);
    return web.json(req.arena, .ok, .{ .tags = counts });
}

/// Serializes tag counts as a JSON object mapping each tag to its count.
const TagObject = struct {
    counts: []const store.TagCount,

    pub fn jsonStringify(self: TagObject, jw: anytype) !void {
        try jw.beginObject();
        for (self.counts) |entry| {
            try jw.objectField(entry.tag);
            try jw.write(entry.count);
        }
        try jw.endObject();
    }
};

test TagObject {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    const empty = try web.json(arena.allocator(), .ok, TagObject{ .counts = &.{} });
    try std.testing.expectEqualStrings("{}", empty.body);
    const res = try web.json(arena.allocator(), .ok, .{ .notes = 3, .tags = TagObject{ .counts = &.{
        .{ .tag = "x", .count = 2 },
        .{ .tag = "y", .count = 1 },
    } } });
    try std.testing.expectEqualStrings("{\"notes\":3,\"tags\":{\"x\":2,\"y\":1}}", res.body);
}

//! notes: a small notes store over HTTP, backed by SQLite.
//!
//! Usage: NOTES_DB=<path> app <port>

const std = @import("std");
const Server = @import("Server.zig");
const Store = @import("Store.zig");

const log = std.log.scoped(.main);

pub fn main(init: std.process.Init) !void {
    const arena = init.arena.allocator();
    const args = try init.minimal.args.toSlice(arena);
    if (args.len != 2) {
        std.process.fatal("usage: {s} <port>", .{if (args.len > 0) args[0] else "app"});
    }
    const port = std.fmt.parseInt(u16, args[1], 10) catch
        std.process.fatal("invalid port: {s}", .{args[1]});

    const db_path = init.environ_map.get("NOTES_DB") orelse
        std.process.fatal("the NOTES_DB environment variable must name the database file", .{});

    var store = Store.open(init.io, try arena.dupeZ(u8, db_path)) catch |err|
        std.process.fatal("cannot open database {s}: {t}", .{ db_path, err });
    defer store.close();

    var server: Server = .{ .gpa = init.gpa, .io = init.io, .store = &store, .options = .{} };
    try server.serve(.{ .ip4 = .loopback(port) });
}

