//! The note type and the validation of note input (`POST /notes`, `PUT /notes/{id}`).

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const max_title_len = 200;
pub const max_tag_len = 32;

/// A stored note, serialized as-is in responses.
pub const Note = struct {
    id: i64,
    title: []const u8,
    body: []const u8,
    /// Sorted ascending, without duplicates.
    tags: []const []const u8,
};

/// A validated `{title, body?, tags?}` request body.
pub const NoteInput = struct {
    /// Trimmed, 1–200 characters.
    title: []const u8,
    body: []const u8 = "",
    /// Valid tags, sorted ascending, without duplicates.
    tags: []const []const u8 = &.{},
};

/// Why an input was rejected; `message` is meant for the client.
pub const Diagnostic = struct {
    message: []const u8 = "",
};

pub const ParseError = error{ InvalidInput, OutOfMemory };

/// Parses and validates a note request body. All returned memory is owned by
/// `arena`. On `error.InvalidInput`, `diag.message` says why.
pub fn parseNoteInput(arena: Allocator, json_text: []const u8, diag: *Diagnostic) ParseError!NoteInput {
    // Duplicate keys are valid JSON; like most parsers, the last one wins.
    const options: std.json.ParseOptions = .{ .duplicate_field_behavior = .use_last };
    const root = std.json.parseFromSliceLeaky(std.json.Value, arena, json_text, options) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        else => return invalid(diag, "body is not valid JSON"),
    };
    const object = switch (root) {
        .object => |o| o,
        else => return invalid(diag, "body must be a JSON object"),
    };

    const title = switch (object.get("title") orelse return invalid(diag, "title is required")) {
        .string => |s| std.mem.trim(u8, s, " "),
        else => return invalid(diag, "title must be a string"),
    };
    const title_len = std.unicode.utf8CountCodepoints(title) catch title.len;
    if (title_len == 0) return invalid(diag, "title must not be empty");
    if (title_len > max_title_len) return invalid(diag, "title must be at most 200 characters");

    const body = if (object.get("body")) |value| switch (value) {
        .string => |s| s,
        else => return invalid(diag, "body must be a string"),
    } else "";

    const tags = if (object.get("tags")) |value| switch (value) {
        .array => |array| try normalizeTags(arena, array.items, diag),
        else => return invalid(diag, "tags must be an array of strings"),
    } else &.{};

    return .{ .title = title, .body = body, .tags = tags };
}

/// A tag is 1–32 characters from `a-z`, `0-9` and `-`.
pub fn isValidTag(tag: []const u8) bool {
    if (tag.len == 0 or tag.len > max_tag_len) return false;
    for (tag) |ch| switch (ch) {
        'a'...'z', '0'...'9', '-' => {},
        else => return false,
    };
    return true;
}

fn normalizeTags(arena: Allocator, values: []const std.json.Value, diag: *Diagnostic) ParseError![]const []const u8 {
    const tags = try arena.alloc([]const u8, values.len);
    for (values, tags) |value, *tag| {
        tag.* = switch (value) {
            .string => |s| s,
            else => return invalid(diag, "tags must be an array of strings"),
        };
        if (!isValidTag(tag.*)) return invalid(diag, "each tag must be 1-32 characters from a-z, 0-9 and -");
    }
    std.mem.sortUnstable([]const u8, tags, {}, lessThan);

    // Drop adjacent duplicates in place.
    var len: usize = 0;
    for (tags) |tag| {
        if (len > 0 and std.mem.eql(u8, tags[len - 1], tag)) continue;
        tags[len] = tag;
        len += 1;
    }
    return tags[0..len];
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

fn invalid(diag: *Diagnostic, message: []const u8) error{InvalidInput} {
    diag.message = message;
    return error.InvalidInput;
}

const testing = std.testing;

fn expectInvalid(json_text: []const u8) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var diag: Diagnostic = .{};
    try testing.expectError(error.InvalidInput, parseNoteInput(arena.allocator(), json_text, &diag));
    try testing.expect(diag.message.len > 0);
}

test "parseNoteInput applies defaults, trims the title and normalizes tags" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var diag: Diagnostic = .{};

    const minimal = try parseNoteInput(arena.allocator(), "{\"title\":\"first\"}", &diag);
    try testing.expectEqualStrings("first", minimal.title);
    try testing.expectEqualStrings("", minimal.body);
    try testing.expectEqual(@as(usize, 0), minimal.tags.len);

    const full = try parseNoteInput(
        arena.allocator(),
        "{\"title\":\"  second  \",\"body\":\"text\",\"tags\":[\"work\",\"b-2\",\"work\"],\"extra\":1}",
        &diag,
    );
    try testing.expectEqualStrings("second", full.title);
    try testing.expectEqualStrings("text", full.body);
    try testing.expectEqual(@as(usize, 2), full.tags.len);
    try testing.expectEqualStrings("b-2", full.tags[0]);
    try testing.expectEqualStrings("work", full.tags[1]);

    const repeated = try parseNoteInput(arena.allocator(), "{\"title\":\"a\",\"title\":\"b\"}", &diag);
    try testing.expectEqualStrings("b", repeated.title);
}

test "parseNoteInput counts title length in characters" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    var diag: Diagnostic = .{};
    // 200 two-byte characters: 400 bytes, still valid.
    const title = "é" ** 200;
    const input = try parseNoteInput(arena.allocator(), "{\"title\":\"" ++ title ++ "\"}", &diag);
    try testing.expectEqualStrings(title, input.title);
    try expectInvalid("{\"title\":\"" ++ "a" ** 201 ++ "\"}");
}

test "parseNoteInput rejects invalid input" {
    try expectInvalid("{\"title\": ");
    try expectInvalid("[]");
    try expectInvalid("\"title\"");
    try expectInvalid("{}");
    try expectInvalid("{\"title\":3}");
    try expectInvalid("{\"title\":\"   \"}");
    try expectInvalid("{\"title\":\"x\",\"body\":3}");
    try expectInvalid("{\"title\":\"x\",\"body\":null}");
    try expectInvalid("{\"title\":\"x\",\"tags\":\"a\"}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[1]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"Bad\"]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"\"]}");
    try expectInvalid("{\"title\":\"x\",\"tags\":[\"" ++ "a" ** 33 ++ "\"]}");
}

test isValidTag {
    try testing.expect(isValidTag("a"));
    try testing.expect(isValidTag("b-2"));
    try testing.expect(isValidTag("a" ** 32));
    try testing.expect(!isValidTag(""));
    try testing.expect(!isValidTag("a" ** 33));
    try testing.expect(!isValidTag("Work"));
    try testing.expect(!isValidTag("a_b"));
    try testing.expect(!isValidTag("a b"));
}

//! Maps a request to its handler. Every route of the service is declared
//! here, so adding or completing an endpoint only touches its file in
//! `src/api/`.
//!
//! | Route          | Methods            | Handlers                          |
//! |----------------|--------------------|-----------------------------------|
//! | `/health`      | GET                | `api/health.zig`                  |
//! | `/notes`       | GET, POST          | `api/list.zig`, `api/notes.zig`   |
//! | `/notes/{id}`  | GET, PUT, DELETE   | `api/notes.zig`, `api/crud.zig`   |
//! | `/stats`       | GET                | `api/stats.zig`                   |
//! | `/tags`        | GET                | `api/stats.zig`                   |

const std = @import("std");
const web = @import("web.zig");
const health = @import("api/health.zig");
const notes = @import("api/notes.zig");
const crud = @import("api/crud.zig");
const list = @import("api/list.zig");
const stats = @import("api/stats.zig");

const Request = web.Request;
const Response = web.Response;

pub const Route = union(enum) {
    health,
    notes,
    /// `/notes/{segment}`; the segment is not validated yet.
    note: []const u8,
    stats,
    tags,
};

pub fn match(path: []const u8) ?Route {
    if (std.mem.eql(u8, path, "/health")) return .health;
    if (std.mem.eql(u8, path, "/notes")) return .notes;
    if (std.mem.eql(u8, path, "/stats")) return .stats;
    if (std.mem.eql(u8, path, "/tags")) return .tags;
    if (std.mem.startsWith(u8, path, "/notes/")) {
        const segment = path["/notes/".len..];
        if (segment.len > 0 and std.mem.indexOfScalar(u8, segment, '/') == null) return .{ .note = segment };
    }
    return null;
}

pub fn dispatch(req: *Request) !Response {
    const route = match(req.path) orelse return notFound(req);
    switch (route) {
        .health => return switch (req.method) {
            .GET, .HEAD => health.get(req),
            else => methodNotAllowed(req, "GET"),
        },
        .notes => return switch (req.method) {
            .GET, .HEAD => list.list(req),
            .POST => notes.create(req),
            else => methodNotAllowed(req, "GET, POST"),
        },
        .note => |segment| {
            const allow = "GET, PUT, DELETE";
            switch (req.method) {
                .GET, .HEAD, .PUT, .DELETE => {},
                else => return methodNotAllowed(req, allow),
            }
            const id = parseId(segment) orelse return web.jsonError(req.arena, .not_found, "note not found");
            return switch (req.method) {
                .GET, .HEAD => notes.show(req, id),
                .PUT => crud.update(req, id),
                .DELETE => crud.remove(req, id),
                else => unreachable,
            };
        },
        .stats => return switch (req.method) {
            .GET, .HEAD => stats.stats(req),
            else => methodNotAllowed(req, "GET"),
        },
        .tags => return switch (req.method) {
            .GET, .HEAD => stats.tags(req),
            else => methodNotAllowed(req, "GET"),
        },
    }
}

/// A note id: a positive decimal integer, digits only.
pub fn parseId(segment: []const u8) ?i64 {
    for (segment) |ch| if (!std.ascii.isDigit(ch)) return null;
    const id = std.fmt.parseInt(i64, segment, 10) catch return null;
    return if (id > 0) id else null;
}

fn notFound(req: *Request) !Response {
    return web.jsonError(req.arena, .not_found, "not found");
}

fn methodNotAllowed(req: *Request, allow: []const u8) !Response {
    var res = try web.jsonError(req.arena, .method_not_allowed, "method not allowed");
    res.allow = allow;
    return res;
}

test match {
    try std.testing.expectEqual(Route.health, match("/health").?);
    try std.testing.expectEqual(Route.notes, match("/notes").?);
    try std.testing.expectEqualStrings("12", match("/notes/12").?.note);
    try std.testing.expectEqual(null, match("/notes/"));
    try std.testing.expectEqual(null, match("/notes/1/x"));
    try std.testing.expectEqual(null, match("/health/"));
    try std.testing.expectEqual(null, match("/nope"));
}

test parseId {
    try std.testing.expectEqual(@as(?i64, 7), parseId("7"));
    try std.testing.expectEqual(@as(?i64, 9223372036854775807), parseId("9223372036854775807"));
    try std.testing.expectEqual(null, parseId("0"));
    try std.testing.expectEqual(null, parseId("-1"));
    try std.testing.expectEqual(null, parseId("+1"));
    try std.testing.expectEqual(null, parseId("abc"));
    try std.testing.expectEqual(null, parseId("1.0"));
    try std.testing.expectEqual(null, parseId("9223372036854775808"));
}

//! A thin, typed wrapper over the SQLite C API.
//!
//! A `Db` is a single connection. It must not be used from two threads at the
//! same time; `Store` serializes access to it.

const std = @import("std");
const c = @import("sqlite_c");

const log = std.log.scoped(.sqlite);

pub const Error = error{SqliteError};

pub const Db = struct {
    handle: *c.sqlite3,

    pub const OpenOptions = struct {
        /// Milliseconds to wait for a lock held by another connection.
        busy_timeout_ms: c_int = 5000,
    };

    /// Opens (creating it if needed) the database file at `path`.
    pub fn open(path: [:0]const u8, options: OpenOptions) Error!Db {
        var handle: ?*c.sqlite3 = null;
        const flags = c.SQLITE_OPEN_READWRITE | c.SQLITE_OPEN_CREATE | c.SQLITE_OPEN_EXRESCODE;
        const rc = c.sqlite3_open_v2(path.ptr, &handle, flags, null);
        if (rc != c.SQLITE_OK) {
            if (handle) |h| {
                log.err("open {s}: {s}", .{ path, std.mem.span(c.sqlite3_errmsg(h)) });
                _ = c.sqlite3_close_v2(h);
            } else {
                log.err("open {s}: {s}", .{ path, std.mem.span(c.sqlite3_errstr(rc)) });
            }
            return error.SqliteError;
        }
        const db: Db = .{ .handle = handle.? };
        _ = c.sqlite3_busy_timeout(db.handle, options.busy_timeout_ms);
        return db;
    }

    pub fn close(db: Db) void {
        _ = c.sqlite3_close_v2(db.handle);
    }

    /// Runs one or more SQL statements that take no parameters and return no rows.
    pub fn exec(db: Db, sql: [:0]const u8) Error!void {
        var message: [*c]u8 = null;
        const rc = c.sqlite3_exec(db.handle, sql.ptr, null, null, &message);
        if (rc != c.SQLITE_OK) {
            defer c.sqlite3_free(message);
            log.err("exec: {s}", .{if (message) |m| std.mem.span(m) else "unknown error"});
            return error.SqliteError;
        }
    }

    /// Compiles `sql` into a statement. The caller must `finalize` it.
    pub fn prepare(db: Db, sql: []const u8) Error!Statement {
        var stmt: ?*c.sqlite3_stmt = null;
        const rc = c.sqlite3_prepare_v2(db.handle, sql.ptr, @intCast(sql.len), &stmt, null);
        if (rc != c.SQLITE_OK) return db.fail("prepare", rc);
        return .{ .db = db, .handle = stmt.? };
    }

    /// Prepares `sql`, binds `args` (a tuple) and runs it to completion.
    pub fn run(db: Db, sql: []const u8, args: anytype) Error!void {
        var stmt = try db.prepare(sql);
        defer stmt.finalize();
        try stmt.bindAll(args);
        while (try stmt.step()) {}
    }

    pub fn lastInsertRowId(db: Db) i64 {
        return c.sqlite3_last_insert_rowid(db.handle);
    }

    /// Rows modified by the most recent INSERT, UPDATE or DELETE.
    pub fn changes(db: Db) i64 {
        return c.sqlite3_changes64(db.handle);
    }

    pub fn errmsg(db: Db) []const u8 {
        return std.mem.span(c.sqlite3_errmsg(db.handle));
    }

    fn fail(db: Db, what: []const u8, rc: c_int) Error {
        log.err("{s}: {s} ({d})", .{ what, db.errmsg(), rc });
        return error.SqliteError;
    }

    /// Runs `func(db, args...)` inside a transaction: committed if it
    /// returns normally, rolled back if it returns an error.
    pub fn transaction(
        db: Db,
        comptime func: anytype,
        args: anytype,
    ) @typeInfo(@TypeOf(func)).@"fn".return_type.? {
        try db.exec("BEGIN IMMEDIATE");
        errdefer db.exec("ROLLBACK") catch {};
        const result = try @call(.auto, func, .{db} ++ args);
        try db.exec("COMMIT");
        return result;
    }
};

pub const Statement = struct {
    db: Db,
    handle: *c.sqlite3_stmt,

    pub fn finalize(stmt: Statement) void {
        _ = c.sqlite3_finalize(stmt.handle);
    }

    /// Clears bindings and rewinds the statement so it can run again.
    pub fn reset(stmt: Statement) void {
        _ = c.sqlite3_reset(stmt.handle);
        _ = c.sqlite3_clear_bindings(stmt.handle);
    }

    /// Binds `value` to the 1-based parameter `index`. Text and blobs are
    /// bound without copying: they must outlive the statement's execution.
    pub fn bind(stmt: Statement, index: c_int, value: anytype) Error!void {
        const T = @TypeOf(value);
        const rc = switch (@typeInfo(T)) {
            .int, .comptime_int => c.sqlite3_bind_int64(stmt.handle, index, @intCast(value)),
            .float, .comptime_float => c.sqlite3_bind_double(stmt.handle, index, value),
            .bool => c.sqlite3_bind_int(stmt.handle, index, @intFromBool(value)),
            .null => c.sqlite3_bind_null(stmt.handle, index),
            .optional => if (value) |v| return stmt.bind(index, v) else c.sqlite3_bind_null(stmt.handle, index),
            else => blk: {
                const bytes: []const u8 = value;
                break :blk c.sqlite3_bind_text64(stmt.handle, index, bytes.ptr, bytes.len, null, c.SQLITE_UTF8);
            },
        };
        if (rc != c.SQLITE_OK) return stmt.db.fail("bind", rc);
    }

    /// Binds the fields of the tuple `args` to parameters 1, 2, ….
    pub fn bindAll(stmt: Statement, args: anytype) Error!void {
        inline for (args, 1..) |arg, index| try stmt.bind(index, arg);
    }

    /// Advances to the next row: true if a row is available, false when done.
    pub fn step(stmt: Statement) Error!bool {
        return switch (c.sqlite3_step(stmt.handle)) {
            c.SQLITE_ROW => true,
            c.SQLITE_DONE => false,
            else => |rc| stmt.db.fail("step", rc),
        };
    }

    pub fn int(stmt: Statement, column: c_int) i64 {
        return c.sqlite3_column_int64(stmt.handle, column);
    }

    /// The column as text. Only valid until the next `step`, `reset` or
    /// `finalize`; use `textAlloc` to keep it.
    pub fn text(stmt: Statement, column: c_int) []const u8 {
        const ptr = c.sqlite3_column_text(stmt.handle, column) orelse return "";
        const len: usize = @intCast(c.sqlite3_column_bytes(stmt.handle, column));
        return ptr[0..len];
    }

    pub fn textAlloc(stmt: Statement, gpa: std.mem.Allocator, column: c_int) error{OutOfMemory}![]u8 {
        return gpa.dupe(u8, stmt.text(column));
    }
};

test "exec, bind, step and read columns" {
    const db = try Db.open(":memory:", .{});
    defer db.close();

    try db.exec("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT NOT NULL)");
    try db.run("INSERT INTO t (name) VALUES (?1)", .{"alpha"});
    try std.testing.expectEqual(@as(i64, 1), db.lastInsertRowId());
    try db.run("INSERT INTO t (name) VALUES (?1)", .{"beta"});

    const stmt = try db.prepare("SELECT id, name FROM t WHERE id >= ?1 ORDER BY id");
    defer stmt.finalize();
    try stmt.bindAll(.{2});
    try std.testing.expect(try stmt.step());
    try std.testing.expectEqual(@as(i64, 2), stmt.int(0));
    try std.testing.expectEqualStrings("beta", stmt.text(1));
    try std.testing.expect(!try stmt.step());
}

test "transaction rolls back on error" {
    const db = try Db.open(":memory:", .{});
    defer db.close();
    try db.exec("CREATE TABLE t (v INTEGER)");

    const insertThenFail = struct {
        fn f(d: Db, v: i64) !void {
            try d.run("INSERT INTO t (v) VALUES (?1)", .{v});
            return error.Boom;
        }
    }.f;
    try std.testing.expectError(error.Boom, db.transaction(insertThenFail, .{@as(i64, 7)}));

    const stmt = try db.prepare("SELECT count(*) FROM t");
    defer stmt.finalize();
    try std.testing.expect(try stmt.step());
    try std.testing.expectEqual(@as(i64, 0), stmt.int(0));
}

//! Data access for `PUT /notes/{id}` and `DELETE /notes/{id}`.
//!
//! Owner: branch `crud`. Lock the store with `Store.acquire`/`release` and use
//! `sqlite.Db.transaction` for multi-statement writes; reuse the helpers of
//! `store/notes.zig` (`fetch`, `insertTags`, …). Deleting a note deletes its
//! tags (`ON DELETE CASCADE`).

const std = @import("std");
const Store = @import("../Store.zig");
const sqlite = @import("../sqlite.zig");
const model = @import("../model.zig");
const notes = @import("notes.zig");
const Note = model.Note;
const NoteInput = model.NoteInput;

/// Replaces the title, body and tags of note `id` with `input` and returns
/// the updated note, or null if there is no such note. The note refers to the
/// memory of `input`.
pub fn update(store: *Store, id: i64, input: NoteInput) !?Note {
    const db = try store.acquire();
    defer store.release();
    if (!try db.transaction(replaceNote, .{ id, input })) return null;
    return .{ .id = id, .title = input.title, .body = input.body, .tags = input.tags };
}

/// Deletes note `id` and its tags. Returns false if there was no such note.
pub fn remove(store: *Store, id: i64) !bool {
    const db = try store.acquire();
    defer store.release();
    // A single statement: its tags go with it through `ON DELETE CASCADE`.
    try db.run("DELETE FROM notes WHERE id = ?1", .{id});
    return db.changes() > 0;
}

fn replaceNote(db: sqlite.Db, id: i64, input: NoteInput) !bool {
    try db.run("UPDATE notes SET title = ?2, body = ?3 WHERE id = ?1", .{ id, input.title, input.body });
    if (db.changes() == 0) return false;
    try db.run("DELETE FROM note_tags WHERE note_id = ?1", .{id});
    try notes.insertTags(db, id, input.tags);
    return true;
}

const testing = std.testing;

test "update replaces every field and keeps the id" {
    var store = try Store.open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    const created = try notes.create(&store, .{ .title = "old", .body = "text", .tags = &.{ "x", "y" } });
    const updated = (try update(&store, created.id, .{ .title = "new", .tags = &.{ "a", "y" } })).?;
    try testing.expectEqualDeep(Note{ .id = created.id, .title = "new", .body = "", .tags = &.{ "a", "y" } }, updated);
    try testing.expectEqualDeep(updated, (try notes.get(&store, a, created.id)).?);

    // Replacing with identical values still finds the note.
    try testing.expect(try update(&store, created.id, .{ .title = "new", .tags = &.{ "a", "y" } }) != null);
    try testing.expectEqual(null, try update(&store, created.id + 1, .{ .title = "none" }));
}

test "remove deletes the note and its tags, and ids are not reused" {
    var store = try Store.open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    _ = try notes.create(&store, .{ .title = "a" });
    const second = try notes.create(&store, .{ .title = "b", .tags = &.{"t"} });
    try testing.expect(try remove(&store, second.id));
    try testing.expectEqual(null, try notes.get(&store, a, second.id));
    try testing.expect(!try remove(&store, second.id));

    const stmt = try store.db.prepare("SELECT count(*) FROM note_tags");
    defer stmt.finalize();
    try testing.expect(try stmt.step());
    try testing.expectEqual(@as(i64, 0), stmt.int(0));

    const third = try notes.create(&store, .{ .title = "c" });
    try testing.expectEqual(second.id + 1, third.id);
}

//! Data access for `GET /notes`.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Store = @import("../Store.zig");
const sqlite = @import("../sqlite.zig");
const model = @import("../model.zig");
const notes = @import("notes.zig");
const Note = model.Note;

pub const max_limit = 100;

/// The filters of a listing; all of them are combined.
pub const Filter = struct {
    /// Only notes that have this tag.
    tag: ?[]const u8 = null,
    /// Only notes whose title or body contains this text, ignoring ASCII case.
    text: ?[]const u8 = null,
    /// Only notes with an id greater than this.
    after: ?i64 = null,
    /// At most this many notes, 1 to `max_limit`.
    limit: u32 = max_limit,
};

// SQLite's built-in `lower` folds ASCII letters only, which is exactly the
// case-insensitivity the spec asks for, and `instr` needs no escaping of
// `%` and `_` as `LIKE` would. Unset filters are bound as NULL.
const list_sql = "SELECT " ++ notes.note_columns ++ " FROM notes" ++
    \\
    \\WHERE (?1 IS NULL OR EXISTS
    \\        (SELECT 1 FROM note_tags WHERE note_tags.note_id = notes.id AND note_tags.tag = ?1))
    \\  AND (?2 IS NULL OR instr(lower(notes.title), lower(?2)) > 0
    \\                  OR instr(lower(notes.body), lower(?2)) > 0)
    \\  AND (?3 IS NULL OR notes.id > ?3)
    \\ORDER BY notes.id
    \\LIMIT ?4
;

/// The notes matching `filter`, ordered by id ascending, tags included.
/// All memory is owned by `arena`.
pub fn list(store: *Store, arena: Allocator, filter: Filter) ![]const Note {
    std.debug.assert(filter.limit >= 1 and filter.limit <= max_limit);

    const db = try store.acquire();
    defer store.release();

    var result: std.ArrayList(Note) = try .initCapacity(arena, filter.limit);
    {
        const stmt = try db.prepare(list_sql);
        defer stmt.finalize();
        try stmt.bindAll(.{ filter.tag, filter.text, filter.after, filter.limit });
        while (try stmt.step()) result.appendAssumeCapacity(try notes.scanNote(stmt, arena));
    }
    for (result.items) |*note| note.tags = try notes.loadTags(db, arena, note.id);
    return result.items;
}

const testing = std.testing;

fn expectIds(expected: []const i64, actual: []const Note) !void {
    var ids: [max_limit]i64 = undefined;
    for (actual, 0..) |note, i| ids[i] = note.id;
    try testing.expectEqualSlices(i64, expected, ids[0..actual.len]);
}

test "list filters by tag, text and id, and pages with a limit" {
    var store = try Store.open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    _ = try notes.create(&store, .{ .title = "Hello world", .tags = &.{"greet"} });
    _ = try notes.create(&store, .{ .title = "other", .body = "say HELLO", .tags = &.{ "greet", "misc" } });
    _ = try notes.create(&store, .{ .title = "100% done_ok" });

    const all = try list(&store, a, .{});
    try expectIds(&.{ 1, 2, 3 }, all);
    try testing.expectEqualStrings("misc", all[1].tags[1]);

    try expectIds(&.{2}, try list(&store, a, .{ .tag = "misc" }));
    try expectIds(&.{}, try list(&store, a, .{ .tag = "mis" }));
    try expectIds(&.{ 1, 2 }, try list(&store, a, .{ .text = "hELLo" }));
    try expectIds(&.{2}, try list(&store, a, .{ .text = "hello", .tag = "misc" }));
    try expectIds(&.{ 1, 2, 3 }, try list(&store, a, .{ .text = "" }));
    try expectIds(&.{3}, try list(&store, a, .{ .text = "0% d" }));
    try expectIds(&.{3}, try list(&store, a, .{ .text = "_" }));
    try expectIds(&.{}, try list(&store, a, .{ .text = "%%" }));
    try expectIds(&.{ 2, 3 }, try list(&store, a, .{ .after = 1 }));
    try expectIds(&.{ 1, 2, 3 }, try list(&store, a, .{ .after = -5 }));
    try expectIds(&.{2}, try list(&store, a, .{ .after = 1, .limit = 1 }));
    try expectIds(&.{}, try list(&store, a, .{ .after = std.math.maxInt(i64) }));
}

//! Data access for single notes: create and read, plus the building blocks
//! other data-access modules (`crud.zig`, `list.zig`, `stats.zig`) reuse.
//!
//! Public functions taking a `*Store` lock it themselves; those taking a
//! `sqlite.Db` expect the caller to hold the lock (see `Store.acquire`).

const std = @import("std");
const Allocator = std.mem.Allocator;
const Store = @import("../Store.zig");
const sqlite = @import("../sqlite.zig");
const model = @import("../model.zig");
const Note = model.Note;
const NoteInput = model.NoteInput;

/// Columns `scanNote` expects, in order, for a query on `notes`.
pub const note_columns = "notes.id, notes.title, notes.body";

/// Inserts a note and returns it with its new id. The note refers to the
/// memory of `input`.
pub fn create(store: *Store, input: NoteInput) !Note {
    const db = try store.acquire();
    defer store.release();
    const id = try db.transaction(insertNote, .{input});
    return .{ .id = id, .title = input.title, .body = input.body, .tags = input.tags };
}

/// The note with `id`, or null if there is none.
pub fn get(store: *Store, arena: Allocator, id: i64) !?Note {
    const db = try store.acquire();
    defer store.release();
    return fetch(db, arena, id);
}

/// The note with `id`, tags included, or null if there is none.
pub fn fetch(db: sqlite.Db, arena: Allocator, id: i64) !?Note {
    const stmt = try db.prepare("SELECT " ++ note_columns ++ " FROM notes WHERE id = ?1");
    defer stmt.finalize();
    try stmt.bindAll(.{id});
    if (!try stmt.step()) return null;
    var note = try scanNote(stmt, arena);
    note.tags = try loadTags(db, arena, id);
    return note;
}

/// Reads the `note_columns` of the current row. `tags` is left empty.
pub fn scanNote(stmt: sqlite.Statement, arena: Allocator) !Note {
    return .{
        .id = stmt.int(0),
        .title = try stmt.textAlloc(arena, 1),
        .body = try stmt.textAlloc(arena, 2),
        .tags = &.{},
    };
}

/// The tags of note `id`, sorted ascending.
pub fn loadTags(db: sqlite.Db, arena: Allocator, id: i64) ![]const []const u8 {
    const stmt = try db.prepare("SELECT tag FROM note_tags WHERE note_id = ?1 ORDER BY tag");
    defer stmt.finalize();
    try stmt.bindAll(.{id});
    var tags: std.ArrayList([]const u8) = .empty;
    while (try stmt.step()) try tags.append(arena, try stmt.textAlloc(arena, 0));
    return tags.toOwnedSlice(arena);
}

/// Adds `tags` (already validated and deduplicated) to note `id`.
pub fn insertTags(db: sqlite.Db, id: i64, tags: []const []const u8) !void {
    if (tags.len == 0) return;
    const stmt = try db.prepare("INSERT INTO note_tags (note_id, tag) VALUES (?1, ?2)");
    defer stmt.finalize();
    for (tags) |tag| {
        stmt.reset();
        try stmt.bindAll(.{ id, tag });
        while (try stmt.step()) {}
    }
}

fn insertNote(db: sqlite.Db, input: NoteInput) !i64 {
    try db.run("INSERT INTO notes (title, body) VALUES (?1, ?2)", .{ input.title, input.body });
    const id = db.lastInsertRowId();
    try insertTags(db, id, input.tags);
    return id;
}

const testing = std.testing;

test "create assigns increasing ids and get reads notes back" {
    var store = try Store.open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    const first = try create(&store, .{ .title = "first" });
    const second = try create(&store, .{ .title = "second", .body = "text", .tags = &.{ "a", "b" } });
    try testing.expectEqual(@as(i64, 1), first.id);
    try testing.expectEqual(@as(i64, 2), second.id);

    const got = (try get(&store, a, 2)).?;
    try testing.expectEqualDeep(second, got);
    try testing.expectEqual(null, try get(&store, a, 3));
}

//! Data access for `GET /stats` and `GET /tags`.
//!
//! Tags live in `note_tags (note_id, tag)`, indexed by `(tag, note_id)`.
//! Deleting a note cascades to its tags, so counting `note_tags` rows only
//! ever counts tags of existing notes.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Store = @import("../Store.zig");
const sqlite = @import("../sqlite.zig");
const notes = @import("notes.zig");

/// How many notes carry `tag`.
pub const TagCount = struct {
    tag: []const u8,
    count: i64,
};

pub const Stats = struct {
    /// Number of notes.
    notes: i64,
    /// Every tag in use, ordered by tag ascending.
    tags: []const TagCount,
};

pub const TagOrder = enum {
    /// Tag ascending.
    tag,
    /// Count descending, then tag ascending.
    count,
};

/// The number of notes and the per-tag counts, read under one lock so they
/// are consistent with each other.
pub fn stats(store: *Store, arena: Allocator) !Stats {
    const db = try store.acquire();
    defer store.release();
    return .{
        .notes = try countNotes(db),
        .tags = try tagCounts(db, arena, .tag),
    };
}

/// Every tag in use with the number of notes carrying it, in `order`.
pub fn tags(store: *Store, arena: Allocator, order: TagOrder) ![]const TagCount {
    const db = try store.acquire();
    defer store.release();
    return tagCounts(db, arena, order);
}

fn countNotes(db: sqlite.Db) !i64 {
    const stmt = try db.prepare("SELECT count(*) FROM notes");
    defer stmt.finalize();
    _ = try stmt.step();
    return stmt.int(0);
}

/// Expects the caller to hold the store lock.
fn tagCounts(db: sqlite.Db, arena: Allocator, order: TagOrder) ![]const TagCount {
    const select = "SELECT tag, count(*) AS n FROM note_tags GROUP BY tag ORDER BY ";
    const sql = switch (order) {
        .tag => select ++ "tag",
        .count => select ++ "n DESC, tag",
    };
    const stmt = try db.prepare(sql);
    defer stmt.finalize();
    var result: std.ArrayList(TagCount) = .empty;
    while (try stmt.step()) {
        try result.append(arena, .{ .tag = try stmt.textAlloc(arena, 0), .count = stmt.int(1) });
    }
    return result.toOwnedSlice(arena);
}

const testing = std.testing;

test "stats and tags of an empty store" {
    var store = try Store.open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    try testing.expectEqualDeep(Stats{ .notes = 0, .tags = &.{} }, try stats(&store, a));
    try testing.expectEqual(0, (try tags(&store, a, .count)).len);
}

test "tags are counted per note and ordered" {
    var store = try Store.open(testing.io, ":memory:");
    defer store.close();
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    _ = try notes.create(&store, .{ .title = "1", .tags = &.{ "b", "c" } });
    _ = try notes.create(&store, .{ .title = "2", .tags = &.{ "a", "c" } });
    _ = try notes.create(&store, .{ .title = "3", .tags = &.{"b"} });
    const deleted = try notes.create(&store, .{ .title = "4", .tags = &.{ "a", "z" } });
    _ = try notes.create(&store, .{ .title = "5" });
    {
        const db = try store.acquire();
        defer store.release();
        try db.run("DELETE FROM notes WHERE id = ?1", .{deleted.id});
    }

    try testing.expectEqualDeep(Stats{ .notes = 4, .tags = &.{
        .{ .tag = "a", .count = 1 },
        .{ .tag = "b", .count = 2 },
        .{ .tag = "c", .count = 2 },
    } }, try stats(&store, a));

    try testing.expectEqualDeep(@as([]const TagCount, &.{
        .{ .tag = "b", .count = 2 },
        .{ .tag = "c", .count = 2 },
        .{ .tag = "a", .count = 1 },
    }), try tags(&store, a, .count));
}

//! Request and response types shared by the server, the router and the
//! handlers in `src/api/`.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Store = @import("Store.zig");

pub const Request = struct {
    /// Freed when the response has been sent; allocate everything for the
    /// response here.
    arena: Allocator,
    store: *Store,
    method: std.http.Method,
    /// The target before any `?`, e.g. `/notes/7`. Not percent-decoded.
    path: []const u8,
    /// The raw query string after `?`, without it; empty if there is none.
    query: []const u8,
    /// The request body; empty for methods without one.
    body: []const u8,
};

pub const Response = struct {
    status: std.http.Status,
    body: []const u8 = "",
    content_type: ?[]const u8 = null,
    /// Value of the `Allow` header, sent with 405 responses.
    allow: ?[]const u8 = null,
};

pub const json_content_type = "application/json";

/// A response whose body is `value` serialized as JSON.
pub fn json(arena: Allocator, status: std.http.Status, value: anytype) Allocator.Error!Response {
    return .{
        .status = status,
        .body = try std.json.Stringify.valueAlloc(arena, value, .{}),
        .content_type = json_content_type,
    };
}

/// A `{"error": message}` response.
pub fn jsonError(arena: Allocator, status: std.http.Status, message: []const u8) Allocator.Error!Response {
    return json(arena, status, .{ .@"error" = message });
}

pub fn text(status: std.http.Status, body: []const u8) Response {
    return .{ .status = status, .body = body, .content_type = "text/plain; charset=utf-8" };
}

pub const no_content: Response = .{ .status = .no_content };

test json {
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    const res = try jsonError(arena.allocator(), .bad_request, "bad \"input\"");
    try std.testing.expectEqual(std.http.Status.bad_request, res.status);
    try std.testing.expectEqualStrings("{\"error\":\"bad \\\"input\\\"\"}", res.body);
    try std.testing.expectEqualStrings(json_content_type, res.content_type.?);
}
